from sys import stdin, stdout, setrecursionlimit
setrecursionlimit(10 ** 7)
nmbr = lambda : int(input())
lst = lambda : list(map(int, input().split()))
from functools import lru_cache

@lru_cache(None)
def fn(cnt):
	if cnt == 0:
		return False
	ans = False
	if cnt >= 1:
		if fn(cnt - 1) == False:
			ans = True
	if not ans and cnt >= 2:
		if fn(cnt - 2) == False:
			ans = True
	return ans
for _ in range(nmbr()):
	n = nmbr()
	s = input()
	cnt = sum((int(ch1 == ch2) for (ch1, ch2) in zip(s, s[1:])))
	if fn(cnt):
		print('JJ')
	else:
		print('Uttu')
